# =============================================================================
# 10_final_figures_legends.R — Final forest plots (main results, sensitivity,
#   secondary outcomes, negative controls) drawn from results_master, single-key
#   summary tables, and figure legends generated by the single text formatter.
# Usage: Rscript scripts/10_final_figures_legends.R
# =============================================================================
suppressPackageStartupMessages({ library(data.table); library(ggplot2) })
OUT <- "output/final"; TAB <- function(f) file.path(OUT, "tables", f); FIG <- function(f) file.path(OUT, "figures", f)
for (f in c("R/20_bootstrap.R", "R/75_positivity_flow.R", "R/77_tables_figs.R", "R/81_exposure_flow_cif.R", "R/83_text_formatter.R")) source(f)
dir.create(file.path(OUT, "derived_data"), showWarnings = FALSE)
file.copy("output/analysis/derived_data/analysis_spec_v32.rds", file.path(OUT, "derived_data", "analysis_spec_v32.rds"), overwrite = TRUE)
rmt <- readRDS(file.path(OUT, "results", "results_master.rds"))

# ---- tables à clé unique
num1 <- function(s) suppressWarnings(as.numeric(sub(" .*", "", s)))
ex <- fread(TAB("exposure_description_v33.csv"))[, .(key = paste(variable, arm), characteristic, arm, value_unweighted = num1(unweighted), value_overlap_weighted = num1(overlap_weighted))]
fwrite(ex, TAB("exposure_keyed_v33.csv"))
mb <- fread(TAB("microbiology_v33.csv"))[, .(key = paste(indicator, treatment), pct_unweighted, pct_overlap_weighted, n, n_yes)]
fwrite(mb, TAB("microbiology_keyed_v33.csv"))
code <- c("AKI by day 7 (all criteria)" = "inc", "+0.3 mg/dL within 48 h only" = "abs", ">=1.5x the 7-day minimum only" = "rel",
          "Both creatinine criteria" = "both", "RRT only" = "rrt", "Confirmed AKI (persistent >=48 h) among AKI" = "conf")
tg <- fread(TAB("aki_trigger_v33.csv"))[, key := paste(fifelse(grepl("^Early", population), "early", "broad"), treatment, code[criterion])]
fwrite(tg, TAB("aki_trigger_keyed_v33.csv"))
xb <- fread(TAB("excluded_no_baseline_vs_included_v33.csv"))[, key := fifelse(grepl("^Excluded", group), "excluded", "included")]
fwrite(xb, TAB("excluded_no_baseline_keyed_v33.csv"))
cx <- fread(TAB("ps_complexity_v33.csv"))
cx[, key := paste0(fifelse(grepl("^Early", population), "early", "broad"), "_", fifelse(grepl("^Parsimonious", specification), "parsimonious", ps_method))]
fwrite(cx, TAB("ps_complexity_keyed_v33.csv"))

mc <- c("Creatinine (mg/dL)" = "creat", "Urea nitrogen (mg/dL)" = "bun", "Urea-to-creatinine ratio" = "ratio")
trk <- rbind(fread(TAB("trajectories_v33.csv"))[, set := "all"], fread(TAB("trajectories_restricted_d5_7_v33.csv"))[, set := "d5_7"])
trk[, key := paste(fifelse(grepl("^Early", population), "early", "broad"), set, mc[marker], day)]
fwrite(trk, TAB("trajectories_keyed_v33.csv"))

ark <- fread(TAB("cumulative_incidence_at_risk_v33.csv"))[, key := paste(fifelse(grepl("^Early", population), "early", "broad"), arm, day)]
fwrite(ark, TAB("cumulative_incidence_at_risk_keyed_v33.csv"))

# ---- forest plots depuis results_master v3.3
row <- function(id, lab, prim = FALSE) { r <- rmt[analysis_id == id]; data.table(label = lab, rd = r$rd, rd_lo = r$rd_ci_low, rd_hi = r$rd_ci_high, is_primary = prim) }
main_rows <- rbind(row("primary_early_ato", "Early (primary) | PTZ vs meropenem | ATO", TRUE),
                   row("secondary_broad_ato", "Broad | PTZ vs meropenem | ATO"),
                   row("three_arm_ptz_vs_mero", "Three-arm (early) | PTZ vs meropenem | generalized ATO"),
                   row("three_arm_ptz_vs_cef", "Three-arm (early) | PTZ vs cefepime | generalized ATO"),
                   row("three_arm_cef_vs_mero", "Three-arm (early) | cefepime vs meropenem | generalized ATO"),
                   row("acorn_aki_d7", "ACORN emulation | PTZ vs cefepime | ATO"))
fwrite(main_rows, TAB("forest_main_rows_v33.csv"))
save_fig_v32(fig_forest_v32(main_rows), FIG("fig5_forest_main"), 18, 7)
lab_of <- function(r) substr(paste(r$population, "|", sub("^[^:]*: ", "", r$description)), 1, 95)
sens <- rmt[population %in% c("Early (primary)", "Broad (secondary)") & role %in% c("SENSITIVITY", "STRATIFIED") &
              outcome %in% c("outcome_primary", "aki_d7_dailymax_v31", "outcome_moss_s3b", "outcome_moss_s4b")]
save_fig_v32(fig_forest_v32(sens[, .(label = lab_of(.SD), rd, rd_lo = rd_ci_low, rd_hi = rd_ci_high, is_primary = FALSE)]), FIG("efig_forest_sensitivity"), 22, 19)
nc <- rmt[role == "NEGATIVE_CONTROL"]
save_fig_v32(fig_forest_v32(nc[, .(label = substr(paste(population, "|", sub("^[^:]*: negative control, ", "", description)), 1, 95), rd, rd_lo = rd_ci_low, rd_hi = rd_ci_high, is_primary = FALSE)],
                            "Risk difference for the negative-control outcome, percentage points (95% CI)"), FIG("efig_forest_negative_controls"), 22, 10)
sec <- rmt[role == "SECONDARY" & population %in% c("Early (primary)", "Broad (secondary)") & !grepl("_ato$", analysis_id)]
save_fig_v32(fig_forest_v32(sec[, .(label = lab_of(.SD), rd, rd_lo = rd_ci_low, rd_hi = rd_ci_high, is_primary = FALSE)],
                            "Risk difference for secondary outcomes, percentage points (95% CI)"), FIG("efig_forest_secondary"), 20, 14)

# ---- légendes (formateur unique)
dir.create(file.path(OUT, "figure_legends"), showWarnings = FALSE)
writeLines(legends_v33(rmt, fread(TAB("n_by_analysis_v32.csv")), function(f) fread(TAB(f))), file.path(OUT, "figure_legends", "legends.md"))
cat("10_final_figures_legends : OK\n")
